function highlightCode(src,name){const lang=codeLang(name),s=String(src??'');let out='',i=0;const esc=E;const kw=new Set(['const','let','var','function','return','if','else','for','while','new','class','extends','import','from','export','default','async','await','try','catch','throw','switch','case','break','continue','typeof','in','of','this','true','false','null','undefined']);while(i<s.length){let c=s[i];if((c==='"'||c==="'"||c==='`')){let q=c,j=i+1;while(j<s.length){if(s[j]==='\\'){j+=2;continue}if(s[j]===q){j++;break}j++}out+='<span class="tok-str">'+esc(s.slice(i,j))+'</span>';i=j;continue}if(c==='/'&&s[i+1]==='/'){let j=s.indexOf('\n',i);if(j<0)j=s.length;out+='<span class="tok-comment">'+esc(s.slice(i,j))+'</span>';i=j;continue}if(c==='/'&&s[i+1]==='*'){let j=s.indexOf('*/',i+2);j=j<0?s.length:j+2;out+='<span class="tok-comment">'+esc(s.slice(i,j))+'</span>';i=j;continue}if(lang==='mcfunction'&&c==='/'){let j=s.indexOf('\n',i);if(j<0)j=s.length;out+='<span class="tok-cmd">'+esc(s.slice(i,j))+'</span>';i=j;continue}if(/[0-9]/.test(c)&&(!i||/[^\w.$]/.test(s[i-1]))){let m=s.slice(i).match(/^(?:0x[\da-f]+|\d+(?:\.\d+)?)/i),v=m?m[0]:c;out+='<span class="tok-num">'+esc(v)+'</span>';i+=v.length;continue}if(/[A-Za-z_$]/.test(c)){let m=s.slice(i).match(/^[A-Za-z_$][\w$]*/),v=m?m[0]:c,j=i+v.length,k=j;while(/\s/.test(s[k]||''))k++;if(lang==='json'&&s[k]===':')out+='<span class="tok-key">'+esc(v)+'</span>';else if(kw.has(v))out+='<span class="tok-kw">'+esc(v)+'</span>';else out+=esc(v);i=j;continue}out+=esc(c);i++}return out||' '}
function ideRefresh(){const ta=document.querySelector('#creatorCode');if(!ta)return;const pre=document.querySelector('#creatorHighlight');const gutter=document.querySelector('#creatorGutter');const f=creatorData().files[Number(S.creatorSelected)];const val=ta.value;if(f)f.content=val;if(pre)pre.innerHTML=highlightCode(val,f?.name);if(gutter)gutter.innerHTML=Array.from({length:Math.max(1,val.split('\n').length)},(_,i)=>i+1).join('<br>');const status=document.querySelector('#creatorIdeStatus');if(status)status.textContent=`${codeLang(f?.name).toUpperCase()} · ${val.length} chars · ${val.split('\n').length} lines`;bindCreatorIDE()}
