async function api(action,body){const r=await fetch('/api',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({action,...body})});let j={};try{j=await r.json()}catch(e){}if(!r.ok){const d=j.detail||j.error||('HTTP '+r.status);S.dbErr=d;throw new Error(j.error||'Server error ('+r.status+')')}return j}
async function sync(){const j=await api('state');S.users=j.users;S.posts=j.posts;S.comments=j.comments;S.me=j.me;S.saves=j.me?{[j.me]:{ids:j.saves}}:{};S.peers=j.peers;S.visits=j.visits;S.myBan=j.myBan||0;S.mine=j.mine;S.packages=j.packages||[];S.txns=j.txns||[];S.mytops=j.mytops||[];S.pend=j.pend||[];S.following=j.following||[];S.followers=j.followers||[];S.fcount=j.fcount||{};S.gcount=j.gcount||{};S.notifs=j.notifs||[];S.unreadN=j.unreadN||0;S.unreadM=j.unreadM||0;S.reports=j.reports||[];S.dbOk=true;render()}
async function getSb(){if(!sb){const c=await api('config'),m=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');sb=m.createClient(c.url,c.anon)}return sb}
async function up(file,kind,name,type){const j=await api('signupload',{kind,name}),c=await getSb(),r=await c.storage.from(j.bucket||'uploads').uploadToSignedUrl(j.path,j.token,file,{contentType:type||'application/octet-stream'});if(r.error)throw r.error;return kind==='proof'?j.path:j.url}
document.addEventListener('dragover',e=>{const d=e.target.closest('#creatorDrop');if(d){e.preventDefault();d.classList.add('drag')}});
document.addEventListener('dragleave',e=>{const d=e.target.closest('#creatorDrop');if(d&&!d.contains(e.relatedTarget))d.classList.remove('drag')});
document.addEventListener('drop',async e=>{const d=e.target.closest('#creatorDrop');if(!d)return;e.preventDefault();d.classList.remove('drag');const c=creatorData();for(const file of [...(e.dataTransfer?.files||[])]){const rel=(file.webkitRelativePath||file.name).replace(/\\/g,'/');let folder=rel.includes('/')?rel.slice(0,rel.lastIndexOf('/')):(S.creatorPath||'');const name=rel.split('/').pop();if(!folder)folder=S.creatorPath||'';if(folder&&!c.folders.includes(folder))c.folders.push(folder);const ext=name.split('.').pop().toLowerCase();const target=ext==='json'&&c.type==='addon'&&/^(items|blocks|recipes|entities|functions|loot_tables)\//.test(folder)?'bp':'rp';c.files.push({name,folder,file,target,type:file.type,size:file.size})}render(true)});
document.addEventListener('change',async e=>{const t=e.target,a=t.dataset.actChange,f=t.files?.[0];if(t.dataset.cf==='folder'){creatorData().files[Number(t.dataset.i)].folder=t.value;return}if(t.dataset.ci&&t.type==='checkbox'){creatorData().items[Number(t.dataset.i)][t.dataset.ci]=t.checked;return}if(t.dataset.cb&&t.type==='checkbox'){creatorData().blocks[Number(t.dataset.i)][t.dataset.cb]=t.checked;return}if(t.dataset.ce&&t.type==='checkbox'){creatorData().entities[Number(t.dataset.i)][t.dataset.ce]=t.checked;return}if((t.id==='creatorFiles'||t.id==='creatorFolderFiles')&&t.files?.length){const c=creatorData();for(const file of [...t.files]){const rel=(file.webkitRelativePath||file.name).replace(/\\/g,'/');let folder=rel.includes('/')?rel.slice(0,rel.lastIndexOf('/')):(S.creatorPath||'');let name=rel.split('/').pop();if(t.id==='creatorFiles'&&!folder)folder=S.creatorPath||'';const ext=name.split('.').pop().toLowerCase();const target=ext==='json'&&c.type==='addon'&&/^(items|blocks|recipes|entities|functions|loot_tables)\//.test(folder)?'bp':'rp';if(folder&&!c.folders.includes(folder))c.folders.push(folder);c.files.push({name,folder,file,target,type:file.type,size:file.size});}render(true);return}if(t.id==='aon'||t.id==='apkg'){const m=S.mine||{};S.ad=S.ad||{on:!!m.autoRenew,pkg:m.autoPkg||(S.packages[0]||{}).id};if(t.id==='aon')S.ad.on=t.checked;else S.ad.pkg=t.value;return}if(t.dataset.f){S[t.dataset.f]=t.value;S.anim=true;render(true);return}if(t.dataset.kc){S.draft[t.dataset.kc]=t.checked;return}if(!a||!f)return;
 try{S.err='Mengunggah...';render(true);
 if(a==='thumb')S.draft.thumb=await up(await shrink(f),'thumb','a.jpg','image/jpeg');
 if(a==='proof'){S.topProof=await up(await shrink(f,1280),'proof','p.jpg','image/jpeg')}if(a==='file'){S.draft.fileUrl=await up(f,'file',f.name,f.type);S.draft.fileName=f.name}
 if(a==='avatar'){const u=await up(await shrink(f),'thumb','a.jpg','image/jpeg');await api('saveavatar',{url:u});await sync()}
 S.err=''}catch(x){S.err='Gagal upload: '+(x.message||'')}render(true)});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-act]');if(!t)return;const a=t.dataset.act,id=t.dataset.id;
 if(a==='bg'&&e.target!==t)return;if(a!=='dl'&&a!=='noreply')e.preventDefault();if(a==='noreply')e.preventDefault();
 try{await act(a,id)}catch(x){S.err='Terjadi kesalahan: '+(x.message||x.code||'');render(true)}});
async function act(a,id){
 if(a==='nav'){S.anim=true;S.open=null;S.modal=null;S.page=id;S.err='';if(id==='wallet'&&!need())return;if(id==='creator'&&!need())return;if(id==='creator'&&!S.creator){const raw=localStorage.getItem('meon_creator_project_v2');if(raw){try{const q=JSON.parse(raw);S.creatorId=q.id||null}catch{}}creatorNew('texture');}if(id==='chat'){S.cu=null;if(!need())return;await loadInbox();return}if(id==='notif'){if(!need())return;S.notifNew=new Set(S.notifs.filter(n=>!n.read).map(n=>n.id));api('readnotifs').then(sync).catch(()=>{})}S.err='';if(id==='upload'&&!S.edit)S.draft={cat:'addon'};if(id==='upload'&&!need())return;render(true);scrollTo(0,0);return}
 else if(a==='tab'){S.tab=id;S.anim=true}
 else if(a==='auth'||a==='authup'){S.anim=true;S.modal='auth';S.mode=a==='auth'?'in':'up';S.err=''}
 else if(a==='swap'){S.mode=S.mode==='up'?'in':'up';S.err=''}
 else if(a==='close'||a==='bg'){S.modal=null;S.open=null;S.reply=null;S.err=''}
 else if(a==='open'){const lp=S.posts.find(x=>x.id===id);if(lp&&lp.locked){S.modal='gate';S.anim=true;render(true);return}S.open=id;S.anim=true;api('view',{id}).then(sync).catch(()=>{})}
 else if(a==='signup'||a==='signin'){const u=val('au').trim().toLowerCase(),p=val('ap');
  try{await api(a,{u,p,d:val('ad')});S.modal=null;S.err='';await sync()}catch(x){S.err=x.message}}
 else if(a==='out'){await api('signout');S.page='home';await sync()}
 else if(a==='like'||a==='save'||a==='delc'||a==='delpost'){if(!need())return;if(a==='delpost'){if(!confirm('Hapus info ini?'))return;S.open=null}await api(a,{id});await sync()}
 else if(a==='dl'){if(!S.me){event.preventDefault();need();return}api('dl',{id}).then(sync).catch(()=>{});return}
 else if(a==='reply'){if(!need())return;S.reply=id;render(true);document.getElementById('ctext')?.focus();return}
 else if(a==='noreply'){S.reply=null}
 else if(a==='comment'){if(!need())return;const tx=val('ctext').trim();if(!tx)return;await api('comment',{pid:id,text:tx,reply:S.reply||''});S.reply=null;S.ctext='';S.scrollEnd=true;await sync()}
 else if(a==='savepost'){if(!need())return;const d=S.draft;if(!(d.title||'').trim())return S.err='Judul wajib diisi',render(true);
  if(!d.link&&!d.fileUrl)return S.err='Isi link atau upload file',render(true);
  const body={id:S.edit||'',title:d.title,desc:d.desc,cat:d.cat,thumb:d.thumb,link:d.link,fileUrl:d.fileUrl,vip:!!d.vip,tags:d.tags||'',gver:d.gver||''};SOC.forEach(([k])=>body['s_'+k]=d['s_'+k]);
  try{await api('savepost',body);S.edit=null;S.draft={cat:'addon'};S.err='';S.page='home';S.tab='new';await sync()}catch(x){S.err=x.message}}
 else if(a==='user'){S.open=null;S.modal=null;S.anim=true;if(id===S.me)S.page='profile';else{S.vu=id;S.page='user'}scrollTo(0,0)}
 else if(a==='follow'){if(!need())return;await api('follow',{u:id});await sync()}
 else if(a==='dm'){if(!need())return;if(!canChat(id)&&!S.convs.some(c=>c.u===id)){alert('Untuk chat, kalian harus saling follow dulu.');return}S.anim=true;S.page='chat';S.cu=id;S.open=null;S.thread=[];S.mtext='';render(true);await loadThread(true);return}
 else if(a==='back'){S.cu=null;await loadInbox();return}
 else if(a==='send'){if(!need())return;const tx=val('mtext').trim();if(!tx)return;await api('send',{to:S.cu,body:tx});S.mtext='';const el=document.getElementById('mtext');if(el)el.value='';await loadThread(false,true);return}
 else if(a==='creatertype'){creatorNew(id);render(true);return}
 else if(a==='creatorcontinue'){S.creatorStage=1;creatorBootstrap(creatorData());render(true);return}
 else if(a==='creatorinfo'){S.creatorStage=0;render(true);return}
 else if(a==='newfile'){const c=creatorData(),folder=S.creatorPath||'RP',name=prompt('Nama file','new_file.json');if(name){const n=name.trim().split('/').pop();const target=c.type==='addon'&&(folder==='BP'||folder.startsWith('BP/'))?'bp':'rp';c.files.push({name:n,folder,target,type:'text/plain',size:0,content:''});S.creatorSelected=String(c.files.length-1);render(true)}return}
 else if(a==='newfolderhere'){const c=creatorData(),base=S.creatorPath||'RP',name=prompt('Nama folder','new_folder');if(name){const f=(base?base+'/':'')+name.trim().replace(/^\/+|\/+$/g,'');if(f&&!c.folders.includes(f))c.folders.push(f);render(true)}return}
 else if(a==='creatorreset'){creatorNew(S.creator?.type||'texture');S.err='';render(true);return}
 else if(a==='additem'){creatorData().items.push({name:'New Item',id:'new_item',kind:'basic',texture:'textures/items/new_item',max:64,damage:0,durability:0,hand:false});render(true);return}
 else if(a==='addblock'){creatorData().blocks.push({name:'New Block',id:'new_block',texture:'textures/blocks/new_block',destroy:1,light:0,friction:0.6,transparent:false});render(true);return}
 else if(a==='addrecipe'){creatorData().recipes.push({type:'shaped',output:'new_item',count:1,a:'minecraft:iron_ingot',b:'minecraft:stick'});render(true);return}
 else if(a==='addentity'){creatorData().entities.push({name:'New Entity',id:'new_entity',health:20,speed:0.25,texture:'textures/entity/new_entity',spawnable:true});render(true);return}
 else if(a==='delitem'){creatorData().items.splice(Number(id),1);render(true);return}
 else if(a==='delblock'){creatorData().blocks.splice(Number(id),1);render(true);return}
 else if(a==='delrecipe'){creatorData().recipes.splice(Number(id),1);render(true);return}
 else if(a==='delentity'){creatorData().entities.splice(Number(id),1);render(true);return}
 else if(a==='delfolder'){creatorData().folders.splice(Number(id),1);render(true);return}
 else if(a==='creatorpath'){S.creatorPath=id||'';S.creatorSelected='';render(true);return}
 else if(a==='previewfile'){openCreatorFile(id);return}
 else if(a==='renamefile'){const f=creatorData().files[Number(id)];if(!f)return;const n=prompt('Nama file baru',f.name);if(n&&n.trim())f.name=n.trim().replace(/[\\/]/g,'_');render(true);return}
 else if(a==='movefile'){const f=creatorData().files[Number(id)];if(!f)return;const n=prompt('Folder tujuan',f.folder||'');if(n!==null){const v=n.trim().replace(/^\/+|\/+$/g,'');f.folder=v;if(v&&!creatorData().folders.includes(v))creatorData().folders.push(v)}render(true);return}
 else if(a==='filemenu'){const f=creatorData().files[Number(id)];if(!f)return;const c=prompt('Aksi file: rename / move / delete', 'rename');if(c==='rename'){const n=prompt('Nama baru',f.name);if(n)f.name=n.trim().replace(/[\\/]/g,'_')}else if(c==='move'){const n=prompt('Folder tujuan',f.folder||'');if(n!==null){f.folder=n.trim().replace(/^\/+|\/+$/g,'');if(f.folder&&!creatorData().folders.includes(f.folder))creatorData().folders.push(f.folder)}}else if(c==='delete'){creatorData().files.splice(Number(id),1);if(String(S.creatorSelected)===String(id))S.creatorSelected=''}render(true);return}
 else if(a==='foldermenu'){const old=id,c=prompt('Aksi folder: rename / delete','rename');if(c==='rename'){const n=prompt('Nama folder baru',old);if(n&&n!==old){creatorData().folders=creatorData().folders.map(x=>x===old?n:x.startsWith(old+'/')?n+x.slice(old.length):x);creatorData().files.forEach(f=>{if(f.folder===old)f.folder=n;else if(f.folder?.startsWith(old+'/'))f.folder=n+f.folder.slice(old.length)})}}else if(c==='delete'){if(confirm('Hapus folder dan isinya dari project?')){creatorData().folders=creatorData().folders.filter(x=>x!==old&&!x.startsWith(old+'/'));creatorData().files=creatorData().files.filter(f=>f.folder!==old&&!f.folder?.startsWith(old+'/'));if(S.creatorPath===old||S.creatorPath.startsWith(old+'/'))S.creatorPath=''}}render(true);return}
 else if(a==='addfolder'){const n=prompt('Nama folder, contoh textures/items/weapons',S.creatorPath?S.creatorPath+'/':'');if(n){const f=n.trim().replace(/^\/+|\/+$/g,'');if(f&&!creatorData().folders.includes(f))creatorData().folders.push(f)}render(true);return}
 else if(a==='uploadfolder'){document.getElementById('creatorFolderFiles')?.click();return}
 else if(a==='creatorbuild'){try{S.err='Membuat pack...';render(true);await exportCreator();S.err='Build selesai ✔ File siap di-download.';render(true)}catch(x){S.err=x.message;render(true)}return}
 else if(a==='invitecreator'){const u=val('creatorInvite').trim().toLowerCase();if(!u)return alert('Masukkan username.');if(!S.creatorId){await saveCreatorCloud();}await api('creator_invite',{projectId:S.creatorId,username:u});await loadCreatorCloud();return}
 else if(a==='removecreator'){if(!S.creatorId)return;await api('creator_remove',{projectId:S.creatorId,username:id});await loadCreatorCloud();return}
 else if(a==='savecreatorcloud'){await saveCreatorCloud();return}
 else if(a==='loadcreatorcloud'){await loadCreatorCloud();return}
 else if(a==='validatecreator'){creatorValidate();return}
 else if(a==='savecreator'){saveCreatorLocal();return}
 else if(a==='loadcreator'){loadCreatorLocal();return}
 else if(a==='delfile'){creatorData().files.splice(Number(id),1);render(true);return}
 else if(a==='addfolder'){const f=val('newfolder').trim().replace(/^\/+|\/+$|\\/g,'/');if(f&&!creatorData().folders.includes(f))creatorData().folders.push(f);render(true);return}
 else if(a==='exportcreator'){try{S.err='Membuat pack...';render(true);await exportCreator();S.err='Export selesai ✔';render(true)}catch(x){S.err=x.message;render(true)}return}
 else if(a==='creatorjson'){manifestPreview();return}
 else if(a==='showmanifest'){const c=creatorData(),x=c.type==='addon'?manifest(c,'resources',c.rp,c.rm,c.bp):manifest(c,'resources',c.rp,c.rm);alert(x);return}
 else if(a==='tag'){S.q='#'+id;S.page='home';S.tab='new';S.open=null;S.anim=true;scrollTo(0,0)}
 else if(a==='pinpost'){const p=S.posts.find(x=>x.id===id);await api('pinpost',{id,pinned:!p.pinned});await sync()}
 else if(a==='report'||a==='reportc'){if(!need())return;const r=prompt('Alasan laporan (mis. spam, tidak pantas, link berbahaya):');if(r===null)return;const c=a==='reportc'?S.comments.find(x=>x.id===id):null;await api('report',{pid:c?c.pid:id,cid:c?c.id:'',reason:r});alert('Laporan terkirim. Terima kasih 🙏');return}
 else if(a==='resolve'){await api('resolve',{id});await sync()}
 else if(a==='buyvip'){if(!need())return;const p=S.packages.find(x=>x.id===id);if(!p||!confirm(`Beli ${p.label} seharga ${rp(p.price)} dari saldo?`))return;await api('buyvip',{pkg:id});alert('VIP aktif ✔ Selamat menikmati!');await sync()}
 else if(a==='saveauto'){const m=S.mine||{},ad=S.ad||{on:!!m.autoRenew,pkg:m.autoPkg||(S.packages[0]||{}).id};await api('setauto',{on:ad.on,pkg:ad.pkg});S.ad=null;await sync();alert(ad.on?'Bayar otomatis diaktifkan.':'Bayar otomatis dinonaktifkan.')}
 else if(a==='sendtop'){if(!need())return;await api('topup',{amount:Number(S.topAmt),path:S.topProof});S.topAmt='';S.topProof='';await sync();alert('Terkirim ✔ Admin akan meninjau bukti pembayaranmu.')}
 else if(a==='review'){S.pid=Number(id);const t=S.pend.find(x=>x.id===S.pid);S.pamt=String(t?t.claimed:'');S.purl='';S.modal='proof';S.anim=true;render(true);const j=await api('proofurl',{id});S.purl=j.url;render(true);return}
 else if(a==='approve'||a==='reject'){if(a==='approve'&&!(Number(S.pamt)>0))return alert('Isi nominal sesuai bukti');if(!confirm(a==='approve'?`Beri saldo ${rp(S.pamt)} ke pengguna ini? Bukti akan dihapus.`:'Tolak top up ini? Bukti akan dihapus.'))return;await api('reviewtopup',{id:S.pid,approve:a==='approve',amount:Number(S.pamt)});S.modal=null;S.purl='';await sync()}
 else if(a==='vipgate'){S.modal='gate';S.anim=true}
 else if(a==='ft'){S.ft=id}
 else if(a==='nochat'){alert('Untuk chat, kalian harus saling follow dulu. Ikuti dia, lalu tunggu dia mengikutimu balik.');return}
 else if(a==='hidepost'){const p=S.posts.find(x=>x.id===id);await api('admpost',{id,hidden:!p.hidden});await sync()}
 else if(a==='editpost'){const p=S.posts.find(x=>x.id===id);S.edit=id;S.open=null;S.draft={...p,tags:(p.tags||[]).join(' ')};S.page='upload';S.err=''}
 else if(a==='cancel'){S.edit=null;S.draft={cat:'addon'};S.page='profile'}
 else if(a==='savetag'){await api('savetag',{u:id,tagText:val('tt_'+id),tagColor:val('tc_'+id),role:document.getElementById('tr_'+id)?val('tr_'+id):'',vipDays:val('tv_'+id),banMin:val('tb_'+id)});await sync()}
 else if(a==='savebio'){await api('savebio',{bio:val('bio'),display:val('dn')});S.err='';await sync()}
 else if(a==='chpw'){try{await api('chpw',{old:val('pw1'),new:val('pw2')});S.err='Password diganti ✔'}catch(x){S.err=x.message}}
 render(true)}
async function init(){render(true);
 try{await sync()}catch(e){S.dbOk=false;return render(true)}
 try{if(!sessionStorage.getItem('mhs_v')){sessionStorage.setItem('mhs_v','1');api('visit').then(sync).catch(()=>{})}}catch(e){}
 const beat=()=>api('beat',{sid}).catch(()=>{});beat();setInterval(beat,30000);setInterval(()=>sync().catch(()=>{}),15000);setInterval(()=>{if(S.page==='chat'&&S.me){S.cu?loadThread(false).catch(()=>{}):loadInbox().catch(()=>{})}},6000);try{navigator.serviceWorker&&navigator.serviceWorker.register('/sw.js')}catch(e){}}
init();
